starter_code:
isogram?: function [word][
    panic "Please implement the isogram? function"
]

test_code:
import.version:3.0.0 {unitt}! 
import {src/isogram}!

describe "Isogram" [
    it "empty string" [
        expects.be:'true? @[isogram? ""]
    ]

    it.skip "isogram with only lower case characters" [
        expects.be:'true? @[isogram? "isogram"]
    ]

    it.skip "word with one duplicated character" [
        expects.be:'false? @[isogram? "eleven"]
    ]

    it.skip "word with one duplicated character from the end of the alphabet" [
        expects.be:'false? @[isogram? "zzyzx"]
    ]

    it.skip "longest reported english isogram" [
        expects.be:'true? @[isogram? "subdermatoglyphic"]
    ]

    it.skip "word with duplicated character in mixed case" [
        expects.be:'false? @[isogram? "Alphabet"]
    ]

    it.skip "word with duplicated character in mixed case, lowercase first" [
        expects.be:'false? @[isogram? "alphAbet"]
    ]

    it.skip "hypothetical isogrammic word with hyphen" [
        expects.be:'true? @[isogram? "thumbscrew-japingly"]
    ]

    it.skip "hypothetical word with duplicated character following hyphen" [
        expects.be:'false? @[isogram? "thumbscrew-jappingly"]
    ]

    it.skip "isogram with duplicated hyphen" [
        expects.be:'true? @[isogram? "six-year-old"]
    ]

    it.skip "made-up name that is an isogram" [
        expects.be:'true? @[isogram? "Emily Jung Schwartzkopf"]
    ]

    it.skip "duplicated character in the middle" [
        expects.be:'false? @[isogram? "accentor"]
    ]

    it.skip "same first and last characters" [
        expects.be:'false? @[isogram? "angola"]
    ]

    it.skip "word with duplicated character and with two hyphens" [
        expects.be:'false? @[isogram? "up-to-date"]
    ]
]
